<?php
declare(strict_types=1);

final class SuperUnitService
{
    public function __construct(private PDO $pdo) {}

    public function snapshot(int $playerId): array
    {
        $p=$this->pdo->prepare('SELECT p.race_id,r.name race,r.attack_modifier,r.defense_modifier FROM players p JOIN races r ON r.id=p.race_id WHERE p.id=?');$p->execute([$playerId]);$player=$p->fetch()?:[];$r=$this->pdo->prepare('SELECT untrained_units,naquadah,super_attack_units,super_defense_units FROM player_resources WHERE player_id=?');$r->execute([$playerId]);$resources=$r->fetch()?:[];$a=$this->pdo->prepare('SELECT academy_level FROM player_unit_stats WHERE player_id=?');$a->execute([$playerId]);$academy=(int)($a->fetchColumn()?:1);$automation=$this->pdo->prepare('SELECT COALESCE(level,0) FROM player_technologies WHERE player_id=? AND technology_key=?');$automation->execute([$playerId,'automation']);$automationLevel=(int)($automation->fetchColumn()?:0);$u=$this->pdo->prepare("SELECT ut.*,COALESCE(pr.level,0) tech_level,COALESCE(t.effect_value,0) tech_effect FROM unit_types ut LEFT JOIN technologies t ON t.technology_key=ut.prerequisite_key LEFT JOIN player_technologies pr ON pr.player_id=? AND pr.technology_key=ut.prerequisite_key WHERE ut.category='elite' ORDER BY ut.name");$u->execute([$playerId]);$roster=[];foreach($u->fetchAll() as $type){$techLevel=(int)$type['tech_level'];$required=(int)$type['prerequisite_level'];$techMet=$techLevel>=$required;$academyMet=$academy>=(int)$type['academy_level_required'];$raceMod=((string)$type['stat_column']==='super_defense_units'?(float)($player['defense_modifier']??1):(float)($player['attack_modifier']??1));$owned=(int)($resources[$type['stat_column']]??0);$power=round((float)$type['base_power']*(float)$type['tier_mastery']*(1+($techLevel*(float)$type['tech_effect']/100))*$raceMod,2);$roster[]=['id'=>(int)$type['id'],'unit_key'=>$type['unit_key'],'name'=>$type['name'],'stat_column'=>$type['stat_column'],'owned'=>$owned,'base_power'=>(int)$type['base_power'],'tier_mastery'=>(float)$type['tier_mastery'],'technology_key'=>$type['prerequisite_key'],'technology_level'=>$techLevel,'technology_required'=>$required,'technology_met'=>$techMet,'academy_level'=>$academy,'academy_required'=>(int)$type['academy_level_required'],'academy_met'=>$academyMet,'race'=>(string)($player['race']??''),'race_modifier'=>$raceMod,'effective_power'=>$power,'strategic_cost'=>(int)$type['strategic_cost'],'recruit_cost'=>(int)$type['recruit_cost'],'seconds_per_unit'=>(int)$type['seconds_per_unit'],'description'=>$type['description'],'ready'=>$techMet&&$academyMet,'lock_reason'=>($techMet&&$academyMet)?'':(!$techMet?'Requires '.(string)$type['prerequisite_key'].' level '.$required:'Requires Academy level '.(int)$type['academy_level_required'])];}return ['roster'=>$roster,'resources'=>$resources,'race'=>$player['race']??'Unknown','formula'=>'elite power = base power × tier mastery × technology × race modifier','total_power'=>array_sum(array_map(fn($x)=>$x['owned']*$x['effective_power'],$roster)),'automation_level'=>$automationLevel,'automation_ready'=>$automationLevel>=1,'states'=>['ready','locked','insufficient-resource','success','error']];
    }

    public function train(int $playerId,string $unitKey,int $quantity): array
    {
        if($quantity<1||$quantity>10000)throw new InvalidArgumentException('Elite training quantity must be between 1 and 10,000.');$this->pdo->beginTransaction();try{$s=$this->pdo->prepare("SELECT * FROM unit_types WHERE unit_key=? AND category='elite' FOR UPDATE");$s->execute([$unitKey]);$type=$s->fetch();if(!$type)throw new RuntimeException('Elite unit type not found.');$s=$this->pdo->prepare('SELECT p.race_id,r.attack_modifier,r.defense_modifier FROM players p JOIN races r ON r.id=p.race_id WHERE p.id=? FOR UPDATE');$s->execute([$playerId]);$player=$s->fetch();if(!$player)throw new RuntimeException('Player not found.');$s=$this->pdo->prepare('SELECT COALESCE(pt.level,0) tech_level FROM technologies t LEFT JOIN player_technologies pt ON pt.player_id=? AND pt.technology_key=t.technology_key WHERE t.technology_key=?');$s->execute([$playerId,$type['prerequisite_key']]);$techLevel=(int)$s->fetchColumn();if($techLevel<(int)$type['prerequisite_level'])throw new RuntimeException('Technology prerequisite not met.');$s=$this->pdo->prepare('SELECT academy_level FROM player_unit_stats WHERE player_id=? FOR UPDATE');$s->execute([$playerId]);if((int)($s->fetchColumn()?:1)<(int)$type['academy_level_required'])throw new RuntimeException('Academy level requirement not met.');$s=$this->pdo->prepare('SELECT untrained_units,naquadah FROM player_resources WHERE player_id=? FOR UPDATE');$s->execute([$playerId]);$r=$s->fetch();if((int)$r['untrained_units']<$quantity)throw new RuntimeException('Not enough untrained population.');$cost=(int)$type['strategic_cost']*$quantity;if((int)$r['naquadah']<$cost)throw new RuntimeException('Not enough Naquadah for elite deployment.');$this->pdo->prepare("UPDATE player_resources SET untrained_units=untrained_units-?,naquadah=naquadah-?,{$type['stat_column']}={$type['stat_column']}+? WHERE player_id=?")->execute([$quantity,$cost,$quantity,$playerId]);$this->pdo->prepare('INSERT INTO game_events(player_id,event_type,entity_type,entity_id,payload) VALUES(?,?,?,?,?)')->execute([$playerId,'super_units_trained','unit_type',$type['id'],json_encode(['unit_key'=>$unitKey,'quantity'=>$quantity,'cost'=>$cost,'technology_level'=>$techLevel],JSON_THROW_ON_ERROR)]);$this->pdo->commit();return ['unit_key'=>$unitKey,'quantity'=>$quantity,'cost'=>$cost,'technology_level'=>$techLevel];}catch(Throwable $e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw $e;}
    }
}
